python3 << 'PYEOF'
import openpyxl

wb = openpyxl.load_workbook('/root/test-supply.xlsx', data_only=True)

# Check all sheets for existing data
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== {name} ===")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 80), max_col=min(ws.max_column, 16), values_only=False):
        vals = []
        for cell in row:
            if cell.value is not None:
                vals.append(f"{cell.coordinate}:{cell.value}")
        if vals:
            print("  " + " | ".join(vals))
PYEOF

